using System;
using System.Drawing;
using System.Net;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace ImageNdi {
public partial class MainWindow {
 readonly SemaphoreSlim controlPending=new SemaphoreSlim(16,16);CompanionControlServer controlServer;long controlGeneration;volatile bool controlClosing;bool remoteSelecting,remoteInvalid;string remoteNumber="";
 readonly Label controlStatus=new Label{Name="CompanionControlStatus",AutoSize=true,MaximumSize=new Size(600,36)};
 readonly Label remoteNumberStatus=new Label{Name="CompanionNumber",AutoSize=true};
 void InitializeCompanionControl(FlowLayoutPanel top){AddButton(top,"Comandi Companion…",ShowControlDialog);top.Controls.Add(controlStatus);top.Controls.Add(remoteNumberStatus);files.SelectionChanged+=delegate{if(!remoteSelecting){remoteInvalid=false;remoteNumber="";RefreshRemoteNumber();}};Disposed+=delegate{controlClosing=true;StopCompanionControl();};ApplyCompanionControl();}
 void RefreshRemoteNumber(){remoteNumberStatus.Text=remoteNumber.Length>0?"Companion numero: "+remoteNumber:remoteInvalid?"Companion: richiamo non valido":"";remoteNumberStatus.ForeColor=remoteInvalid?Color.Firebrick:Color.DarkBlue;}
 void StopCompanionControl(){controlGeneration++;if(controlServer!=null){controlServer.Dispose();controlServer=null;}}
 void ApplyCompanionControl(){StopCompanionControl();remoteNumber="";remoteInvalid=false;RefreshRemoteNumber();if(!settings.Companion.ControlEnabled){controlStatus.Text="Comandi TCP: spenti";controlStatus.ForeColor=Color.DimGray;return;}try{long version=controlGeneration;controlServer=new CompanionControlServer(IPAddress.Parse(settings.Companion.ControlAddress),settings.Companion.ControlPort,line=>DispatchControl(line,version));controlStatus.Text="Comandi TCP: ascolto "+settings.Companion.ControlAddress+":"+controlServer.Port+" · senza autenticazione, solo rete protetta";controlStatus.ForeColor=Color.DarkOrange;}catch(Exception e){controlStatus.Text="Comandi TCP: ERRORE · "+e.Message;controlStatus.ForeColor=Color.Firebrick;}}
 string DispatchControl(string line,long version){if(controlClosing||IsDisposed||!IsHandleCreated)return "ERR Applicazione non pronta";if(!controlPending.Wait(0))return "ERR Applicazione occupata: coda comandi piena";var result=new TaskCompletionSource<string>();int state=0;try{BeginInvoke((Action)delegate{try{if(Interlocked.CompareExchange(ref state,1,0)!=0)return;if(controlClosing||IsDisposed||version!=controlGeneration){result.TrySetResult("ERR Ricezione arrestata");return;}try{result.TrySetResult(ExecuteCompanionCommand(line));}catch(Exception e){result.TrySetResult("ERR "+e.Message);}}finally{controlPending.Release();}});}catch(InvalidOperationException){controlPending.Release();return "ERR Applicazione in chiusura";}if(result.Task.Wait(15000))return result.Task.Result;return Interlocked.CompareExchange(ref state,2,0)==0?"ERR Comando annullato: applicazione occupata":"ERR Tempo scaduto: verificare esito nell'app";}
 string ExecuteCompanionCommand(string line){CompanionCommand command;if(!CompanionCommand.TryParse(line,out command))return "ERR Comando sconosciuto o argomenti non validi";
  switch(command.Name){
   case "DIGIT":if(remoteNumber.Length>=9)return "ERR Massimo 9 cifre";remoteNumber+=command.Value;remoteInvalid=false;RefreshRemoteNumber();return "OK NUMBER "+remoteNumber;
   case "BACKSPACE":if(remoteNumber.Length>0)remoteNumber=remoteNumber.Substring(0,remoteNumber.Length-1);remoteInvalid=false;RefreshRemoteNumber();return "OK NUMBER "+remoteNumber;
   case "CANCEL":remoteNumber="";remoteInvalid=false;RefreshRemoteNumber();return "OK CANCEL";
   case "SELECT":return SelectRemoteNumber(command.Value);
   case "ENTER":if(remoteNumber.Length==0)return "ERR Nessun numero composto";return SelectRemoteNumber(remoteNumber);
   case "NEXT":case "PREV":remoteSelecting=true;try{remoteNumber="";remoteInvalid=false;RefreshRemoteNumber();return files.Navigate(command.Name=="NEXT"?1:-1)?"OK "+command.Name:"ERR Estremo elenco";}finally{remoteSelecting=false;}
   case "NEXT_BLOCK":case "PREV_BLOCK":return NavigateRemoteBlock(command.Name=="NEXT_BLOCK"?1:-1);
   case "GO":if(remoteInvalid||remoteNumber.Length>0)return "ERR Confermare un numero valido con ENTER o SELECT";if(output==null||output.Error!=null)return "ERR Program non attivo";if(pending==null||selectedSource==null||selected==null)return "ERR Nessuna selezione valida";return Cue(false)?"OK GO":"ERR "+status.Text;
   case "PLAY":case "PAUSE":return ControlProgramVideo(command.Name=="PLAY");
   case "CLEAR_FADE":case "CLEAR_CUT":if(output==null||output.Error!=null)return "ERR Program non attivo";ClearProgramWithFade(command.Name=="CLEAR_CUT");return "OK "+command.Name;
  }return "ERR Comando non supportato";
 }
 string ControlProgramVideo(bool play){if(output==null||output.Error!=null)return "ERR Program non attivo";var video=output.CurrentVideo;if(video==null)return "ERR Nessun video in onda";if(play){if(video.Paused)video.SetPaused(false);else if(video.Ended){RestartVideo(true,null);}}else if(!video.Ended)video.SetPaused(true);programTransport.SetVideo(output.CurrentVideo);return play?"OK PLAY":"OK PAUSE";}
 string SelectRemoteNumber(string number){remoteNumber=number;remoteSelecting=true;try{string message;if(!SelectNumber(number,out message)){remoteInvalid=true;RefreshRemoteNumber();return "ERR "+message;}remoteNumber="";remoteInvalid=false;RefreshRemoteNumber();return "OK SELECT "+number;}finally{remoteSelecting=false;}}
 string NavigateRemoteBlock(int direction){int current=settings.Blocks.FindIndex(b=>b.Id==settings.ActiveBlockId),next=current+direction;if(next<0||next>=settings.Blocks.Count)return "ERR Estremo blocchi";remoteSelecting=true;try{remoteNumber="";remoteInvalid=false;RefreshRemoteNumber();settings.ActiveBlockId=settings.Blocks[next].Id;search.Clear();RefreshBlocks();RefreshVisible();files.SelectFirst();Save();return "OK BLOCK "+settings.Blocks[next].Name;}finally{remoteSelecting=false;}}
 void ShowControlDialog(){using(var dialog=new Form{Text="Comandi Companion · TCP in ingresso",Width=650,Height=370,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(12)};var enabled=new CheckBox{Text="Abilita comandi TCP in ingresso",AutoSize=true,Checked=settings.Companion.ControlEnabled};var address=new TextBox{Text=settings.Companion.ControlAddress,Width=240};var port=Number(1,65535,settings.Companion.ControlPort);panel.Controls.Add(enabled);panel.Controls.Add(new Label{Text="Attenzione: comandi senza autenticazione. Usare solo una rete protetta.",AutoSize=true,ForeColor=Color.DarkOrange});panel.Controls.Add(new Label{Text="IP locale di ascolto · 0.0.0.0 = tutte le interfacce",AutoSize=true});panel.Controls.Add(address);panel.Controls.Add(new Label{Text="Porta TCP · diversa dalle notifiche in uscita",AutoSize=true});panel.Controls.Add(port);panel.Controls.Add(new Label{Text="Companion si collega all'IP di questo PC e invia un comando per riga (LF).\r\nNEXT / PREV · NEXT_BLOCK / PREV_BLOCK · SELECT n · GO\r\nDIGIT n · BACKSPACE · CANCEL · ENTER · CLEAR_FADE · CLEAR_CUT · PLAY · PAUSE",AutoSize=true});var buttons=new FlowLayoutPanel{Width=600,Height=35};AddButton(buttons,"Applica",delegate{try{var config=settings.Companion.Copy();config.ControlEnabled=enabled.Checked;config.ControlAddress=address.Text.Trim();config.ControlPort=(int)port.Value;config.Validate();settings.Companion=config;ApplyCompanionControl();Save();if(config.ControlEnabled&&controlServer==null){MessageBox.Show(controlStatus.Text,"Comandi Companion");return;}dialog.DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(e.Message,"Comandi Companion");}});buttons.Controls.Add(new Button{Text="Annulla",AutoSize=true,DialogResult=DialogResult.Cancel});panel.Controls.Add(buttons);dialog.Controls.Add(panel);dialog.ShowDialog(this);}}
}
}
